#include <iostream>
template <typename CharT, typename Traits = std::char_traits<CharT>>
class MyStream : public std::basic_istream<CharT, Traits> {
public:
    explicit MyStream(std::basic_streambuf<CharT, Traits>* sb) : std::basic_istream<CharT, Traits>(sb) {}
    // Additional custom behavior can be added here
};
int main() {
    // Using a string stream as an example stream buffer
    std::stringbuf buf;
    MyStream<char> myStream(&buf);
    buf.sputn("Hello, C++ Templates!", 21);
    std::string output;
    std::getline(myStream, output);
    std::cout << output << std::endl;
    return 0;
}
